def parse_now(value):
    """`now` as a datetime. Accepts 2026-10-14T11:00, with seconds, or with a trailing Z."""
    s = str(value or "").strip().replace("Z", "")
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
